import type { Story } from "./stories";

export const stories2500: Record<number, Story> = {
	2500: {
		index: 2500,
		text: `<p>The local magistrate demands volunteers to pursue one he describes as a foul thief and murderer. However, you know the other by reputation to be a holy man. You join the mission to find out what is behind the magistrate's actions.</p>
<p><b>No Skill:</b> Your team wanders for days in the desert, never finding any trace of the other. You are relieved to have not proven him a thief, at least. [S1]</p>
<p><b>Wilderness Lore, Stealth and Stealing:</b> You know all of the hiding places within two days' walk of this town, and set out on your own, soon finding the holy man. He explains to you that he has witnessed the magistrate himself orchestrating a series of vile crimes. By secret roads you bring the dervish into the court of the prince of this land, and on his testimony the magistrate is beheaded. You are praised for your role in bringing justice. [D1/<b>Robe of Honor</b>]</p>`,
	},
	2501: {
		index: 2501,
		text: `<p>Walking along a lonely road, you hear a strange sound. You discover a soldier making screeching noises. The other claims to be able to speak with birds. A good friend—a hawk—is lost and will not answer to his call. Astounded by the other's claim, you vow to help. You search high and low and discover a small camp. Two bandits are laughing, and beside them in a wooden cage sits a very agitated bird! You walk up boldly and sit down next to them. They draw their weapons, but you assure them you mean them no harm.</p>
<p><b>No Skill:</b> Despite your pleasant air and easy manner, the two criminals remain suspicious. They never let down their guard, and soon take their leave. The soldier will have to find another friend to speak with. [S1]</p>
<p><b>Acting and Disguise, Beguiling, Storytelling:</b> You calmly tell them that you are out looking for a bird, one cursed by a powerful witch. It seems anyone who possesses this bird will be turned into one himself at the first light of dawn. The two men look at you nervously, and then at the bird next to them. One of them leans over and quickly releases the bird, which immediately flies to freedom. You tell the men they were very wise and stay the evening, drinking and laughing with them. [D1/S1/Quick Thinking]</p>`,
	},
	2502: {
		index: 2502,
		text: `<p>You are nursed back to health by an accomplished chirurgeon after an ill-fated adventure. Although very talented in medicine, the other is poor at administration. When healing supplies run low, no one in the city can replenish them. The other, who works with the chirurgeon as a guard, asks that you lead a caravan to a certain city and return with new goods. You agree, pleased to help in any way you can. When you arrive, many weeks later, at the far city, you find that the merchant has greatly increased his prices and the gold you were sent with is insufficient.</p>
<p><em>You can supplement the caravan's coffers with your own wealth or not:</em></p>
<p><em>If you sacrifice a level of Wealth:</em> The other is so impressed with your generosity that he offers to take you as his student of the medical arts. [D1/S1/W−1 (Min: Poor)/Scholarship]</p>
<p><em>If you do not sacrifice a level of Wealth:</em> You return with what you can afford, but the other suspects you of embezzlement. [D1/<em>Scorned</em>]</p>`,
	},
	2503: {
		index: 2503,
		text: `<p>When impressing members of the fairer sex, a sharp wit and easy speech are enormous assets, and a strong back is not always helpful. You watch as the biggest man you have ever seen stumbles and stammers over a young maiden collecting water from a well. He stutters many times, and once almost knocks over her water jug! You approach the strong one, saying, "My friend, you seem to be distressed. Do you wish to court this lovely maiden?" He nods dumbly. You take him to the market and show him many gifts that will win the young maiden's heart. He does not understand. Finally, you decide to show him what to do. You whisper in his ear as he writes bad poetry, sings like a camel in heat, and delivers gifts so heavy that two normal grown men could not lift them.</p>
<p><b>No Skill, Appearance</b> (mandatory): You spend the next few days with the clumsy oaf, and others begin to notice you. Unfortunately, the fair maiden is one of them. [S1/<em>Envious</em> (if you are male) or <em>Scorned</em> (if you are female)]</p>
<p><b>Wisdom:</b> The girl comes to appreciate the large one, but cannot find it in her heart to love him. You, on the other hand, learn quite a bit about courting. [D1/S1/Seduction]</p>`,
	},
	2504: {
		index: 2504,
		text: `<p>A wealthy merchant asks that you retrieve a prized racehorse, stolen from his home by bandits. Angered by the loss of such a magnificent beast, you head out directly, without even negotiating a price for your service. You follow the horse's tracks and find that they are joined by a number of others. In the end, you discover a band of horse thieves with a sizeable herd. The bandits are celebrating their work, contemplating the newfound wealth that will soon be theirs.</p>
<p><b>No Skill:</b> Unwilling to take on so many armed ruffians, and unsure what else to do, you sit down to keep watch. Alas, your intentions are better than your determination; you fall asleep and the bandits ride away before you can act. [S1]</p>
<p><b>Stealth and Stealing:</b> You sneak your way to the side of the horse you have been sent to retrieve. There, you raise a horrible clamor, spooking the horses around you. As they scatter in all directions, you leap upon the merchant's horse and ride off, crouching low in the saddle. The bandits are distracted trying to round up their stolen animals and you escape back to town. [D1/S1/Quick Thinking]</p>`,
	},
	2505: {
		index: 2505,
		text: `<p>A messenger comes from a far off village, asking you to visit a great merchant there to discuss a business proposition: the merchant has had difficulty securing a tutor for his son, and would like you to serve in that capacity. You travel to the village to accept the task, although you protest that another would be better suited.</p>
<p><b>No Skill:</b> Sadly, your humble assessment was correct. In a short time, you are dismissed from service. [S1]</p>
<p><b>Scholarship:</b> The boy proves to be a good student and you a wise teacher. The merchant is greatly pleased. Better yet, the merchant's library turns out to be extraordinary and you are given the run of it. [D1/S1/Scholarship/<em>Respected</em>]</p>`,
	},
	2506: {
		index: 2506,
		text: `<p>While traveling by ship, you hear a loud crash and the sounds of shouting on the deck. The owner of the vessel, a wealthy merchant, thrusts a scimitar into your hands as marauding pirates swarm over the sides of the ship.</p>
<p><b>No Skill:</b> You fight as bravely as you can, but soon you and the merchant are overcome and thrown into the sea. [S1/W−2 (Min: Penniless)]</p>
<p><b>Weapon Use:</b> You are the whirlwind and lay about you with abandon. With you leading the counterattack, the crew drives the pirates from the ship. For the remainder of the journey, you are treated as a prince and given the run of the ship. [D1/S1/Seamanship]</p>`,
	},
	2507: {
		index: 2507,
		text: `<p>On the way to the Holy City, you happen along a traveling band of mendicant dervishes. They have been sorely pressed by monsters, bandits, and the desert. You offer to aid them, protecting them from anything that might wish to interrupt their devotions.</p>
<p><b>No Skill:</b> You keep the holy ones safe, but not without cost. [D1/<em>Wounded</em>]</p>
<p><b>Acting and Disguise, Appearance, Quick Thinking:</b> Through bluff, distraction, and histrionics, you dissuade any who approach from harming the dervishes. The holy ones bless you and honor you. [D2/<em>Blessed</em> (1 use)/<b>Robe of Honor</b>]</p>`,
	},
	2508: {
		index: 2508,
		text: `<p>The Sultan's son has gone missing and a reward is offered for any information on his whereabouts. You devote yourself to the task, and, by luck, discover the errant royal among an order of Sufi dervishes who engage in frenetic meditation in the nearby hills. He has found his place in the world, and wishes to remain. Touched by his devotion, you promise to speak on his behalf at his father's court.</p>
<p><b>No Skill:</b> You are sincere but fail to sway the Sultan, who tosses you in jail for bringing him news he so despises. [D1/<em>Imprisoned</em>]</p>
<p><b>Beguiling:</b> You speak long and eloquently about the grace of Allah and the path the Great One lays before each of his children. "Perhaps the Most High feels that your son requires some time in divine communion in order to become a better ruler. Who are we to challenge or question His august plan?" The Sultan is moved by your devotion and presentation and agrees to allow his son some time to follow his heart before returning to his duty. [D1/S1/Piety]</p>`,
	},
	2509: {
		index: 2509,
		text: `<p>Travel makes for strange bedfellows, and one night you find yourself in the camp of a band of wandering dervishes. After dinner, their leader approaches you and asks if you will join them in their divine dance. He explains that adding another will aid in the balance of their ceremony. You accept, dancing and whirling along with them into the wee hours of the night.</p>
<p><em>Roll two dice, adding one each for Enduring Hardship, Piety, and Wisdom:</em></p>
<p>❖ 2–5: You stumble through the rituals, straining your back and souring your mood. You make a mess of the devotion. [D1/<em>Scorned</em>]</p>
<p>❖ 6–8: You perform admirably but cannot honestly say that you are deeply moved. [S1]</p>
<p>❖ 9–11: For a brief moment your mind lifts you from your body and you feel as if you could touch the divine. [D1/<em>Blessed</em> (1 use)]</p>
<p>❖ 12+: Affirmation is truly the guidebook for the soul. [D1/S1/Piety]</p>`,
	},
	2510: {
		index: 2510,
		text: `<p>In a particularly desolate spot along the road, you see a figure lying prone in the hot sun. Cautiously, you approach, prodding the wretch with your walking stick. When the unfortunate does not respond, you rifle through the tattered robes, finding a few greasy coins. [D1]</p>`,
	},
	2511: {
		index: 2511,
		text: `<p>Sitting on the shore of a beautiful lake, you espy a gold-embossed, ivory-bound codex of the Koran floating in the water. You look left and right and, seeing no one, place the beautiful book in your sack. You quickly gather your things. As you walk away, you hear shouts of "Thief!" from behind you—an obviously poor man is approaching!</p>
<p><b>No Skill:</b> Ashamed, you return the book to the other. He admonishes you, explaining that he is on pilgrimage, and plans to place this exquisite book in the sacred dome at Mecca. [D1/<em>Accursed</em>]</p>
<p><b>Quick Thinking:</b> As the man gets closer, you throw yourself at his feet. "I had feared the book's true owner had come to ill end and I was desperate to return it to the mosque. But praise Allah that you are alive!" The red-faced man apologizes for his mistake, and offers you his only remaining possession as a reward. [S2/Lose Piety/<b>Copper Drum</b>]</p>`,
	},
	2512: {
		index: 2512,
		text: `<p>Sand burns your feet as you stumble through the merciless desert. By providence, a rickety shack appears in the shade of several large rocks. Using your last vestiges of strength, you push your way inside. There you find a threadbare cot, a broken chair, and a wobbly table. A fine bottle of wine sits on the table. You accept this oddity with little more than a passing thought, gulp down the excellent vintage, and slump exhausted on the cot.</p>
<p><b>No Skill:</b> You awake to find a large man looming over you, bearing a stick in one hand and almost superhuman rage on his face. You have consumed his last treasure, leaving him with nothing to barter for food. He beats you soundly, calling upon the wrath of Allah to teach you a lesson in right and wrong. [S1/<em>Wounded</em>]</p>
<p><b>Stealth and Stealing:</b> You awake just moments before the old wooden door swings open, and you quickly hide under the bed. You see the large feet of an obviously powerful man move to the table. A scream of rage sounds, dissolving into wretched sobs of despair. As he cries, you stealthily exit the shack and sprint off into the wilderness. [D2/Stealth and Stealing]</p>`,
	},
	2513: {
		index: 2513,
		text: `<p>Jailed unjustly, you are finally released. As you depart, you pass a particularly dank and smelly cell. A shape huddled in the darkness crawls forward, squinting into the light. "I beg you. Pay for my freedom, and I will reward you with a treasure map." The guards push you along, saying, "Ignore that poisoning hussy." You cannot forget the other's words, however. You must get your hands on that map.</p>
<p><b>No Skill:</b> You return to the jail and claim that a prisoner stole a map from you. You point to the other as the culprit. The guards search but find nothing. The maiden cackles at your frustration. [D1/<em>Envious</em>]</p>
<p><b>Beguiling:</b> You sneak into the jail, bribing the guards to let you pass. Outside the maiden's cell, you whisper heart-felt promises that you will return once you have the money. In the process, you trick her into revealing the map's hiding place. You retrieve it and find the treasure. You travel on, putting your promise to the woman out of your mind. [D1/W+2 (Max: Rich)]</p>`,
	},
	2514: {
		index: 2514,
		text: `<p>Through a series of misfortunes involving a princess, ten missing crates of fine silks, a pirate, and an unusually eloquent parrot, you are thrown in an oubliette. To your amazement, you are not alone there—the other, too, is therein captive. The guards drop some bread for you the first day, and then leave longer and longer between visits. In time, you learn that the other captor is hoarding his food. You steal over to her side of the pit while she sleeps and uncover a hidden rock. You steal the bread and gorge yourself. The next morning, the other is removed to be executed. You are ashamed, ruing your choice to steal when you would soon have had the provisions to yourself anyway. [D1/<em>Imprisoned</em>]</p>`,
	},
	2515: {
		index: 2515,
		text: `<p>Wounded by a group of bandits, you escaped into the wilderness. Stumbling into a town, you desperately seek a healer. You are told that the local herbalist might be able to help you, but she has been imprisoned by the magistrate for failing to cure a noble's impotence. You set off from the healer's home, intending to take what you need to survive.</p>
<p><em>Roll two dice, adding one each for Enduring Hardship, Stealth and Stealing, and Wilderness Lore:</em></p>
<p>❖ 2–5: Caught! Guards watch the herbalist's home. You join the good doctor in jail, where, thankfully, she does tend to your wounds. [S1/<em>Imprisoned</em>/Lose <em>Wounded</em>]</p>
<p>❖ 6–10: Surprise! At the healer's home, you find not only the medicines you need, but also a silver vial filled with a strange purple balm. Believing it to be a magical salve, you rub it onto your body in the hopes of an instant cure. Indeed, you are cured by the unguent. You are also turned to the opposite sex. This reminds you that those versed in the arts of healing often are versed in the arts of magic as well. [D1/<em>Sex-Changed</em>/Lose <em>Wounded</em>]</p>
<p>❖ 11+: Success! You steal away into the night with salves and medicines. You also take a golden vial filled with a strange yellow powder with you. Experimenting with the herbs and lotions, you quickly heal your wounds and find that you have happened upon a wondrous item. [D1/Wilderness Lore/Lose <em>Wounded</em>/<b>Yellow Kohl</b>]</p>`,
	},
	2516: {
		index: 2516,
		text: `<p>The other has fallen into hard times because of a streak of ruinous luck. You offer to take over some of his interests—for a share of some of the profit, of course—so that he can concentrate on others. Perhaps together you can each rescue some part of his business.</p>
<p><b>No Skill:</b> You are not up to even some of the task—whatever value was left in what you were given is gone now, along with some money of your own. [S1/W-1 (Min: Respectable)]</p>
<p><b>Bargaining and Evaluation:</b> You excel at the tasks you are assigned, making money and connections for yourself and your new partner. He decides to teach you all he knows about the world and more. [W+2 (Max: Wealthy)/Scholarship/<em>Respected</em>]</p>`,
	},
	2517: {
		index: 2517,
		text: `<p>You spy a small, tattered tent at the mouth of a desolate canyon. Hoping to gain some information about the area, you approach the other who lives therein, a once-wealthy merchant who has fallen on very hard times. "I have passed many times through this valley in my travels, and would be willing to guide you through if you would buy shares in my latest endeavor." You study the wilderness as you weigh your offer.</p>
<p><b>No Skill:</b> The canyon does not appear daunting. You claim you are fine on your own, and ignoring him, you set off into the cursed passage. You travel for days until, dying of thirst and your mind almost gone, you reach the end. [D1/<em>Insane</em>]</p>
<p><b>Wilderness Lore:</b> The area appears unnatural and you decide not to attempt passage alone. Noting the poor health of the other, you offer, instead of investment, to carry the other's goods across the canyon if he acts as a guide. Surprised, the other accepts. Because of the other's intimate knowledge of the area, before you even know it you are both across the canyon. [D1/Bargaining and Evaluation]</p>`,
	},
	2518: {
		index: 2518,
		text: `<p>You are bowed in evening prayer when a shadow passes over you. A figure stands over you, sandals worn, robes torn and stained. He tells you that the place is cursed and that you risk grave harm by remaining. He offers to lend you a charm that will protect you while you pray, but he is desperately hungry and needs food. Unsure of the wretch's claims, you offer only a crust of bread. He demands more.</p>
<p><b>No Skill:</b> You refuse and send him away. Still, you are shaken. You rush through your prayers and depart as quickly as possible. As the night wears on, you are restless, feeling as if you had neglected your duty. [D1]</p>
<p><b>Acting and Disguise:</b> You look at the man in righteous indignation. "A man must show proper respect to Allah, and aid in such an endeavor should not be withheld," you caution. You demand that the old man bow down and pray with you, so you both may benefit from the charm's effect. Intimidated, he takes the bread you offer and complies. [D1/S1/Piety]</p>`,
	},
	2519: {
		index: 2519,
		text: `<p>You have found inside a remote mountain a strange cave lit from within by glowing moss, illuminating a crystal pool. Standing between you and the pool is a stranger, dressed in a loose silk mask embroidered in gold and silver with strange symbols. "You have invaded my cave. Come to steal my treasures. You shall never leave to tell others what you have found!" Thinking quickly, you offer a bargain. If you succeed at a test of the other's choice, you will be shown the way out. If you fail, whatever fate awaits you is well-deserved. The stranger dances in place. "Ah yes, a riddle then?" You nod in confirmation. "What is earth when carried, fire when lit, air when all is said and done, but becomes useless in water?"</p>
<p><b>No Skill:</b> You think for a moment, and then grin. "I believe you refer to wood." The other cackles maniacally, "Wrong!" and disappears in a puff of smoke. [S1]</p>
<p><b>Wisdom:</b> After almost an hour, you address the other, "I believe you refer to the only substance that is normally dry like sand, becomes a ball of flame when lit, and merely smokes when consumed. Water can ruin it... for it is this new creation from the East. Gunpowder." The other nods appreciably, and shows you the way out, granting you one item from his trove before you go. [D2/S1/<b>Treasure</b>]</p>`,
	},
	2520: {
		index: 2520,
		text: `<p>You are approached on the street by an ancient beggar who smells vaguely of camels and old dates. The scruffy one waves a piece of parchment and says, "What would you do for infinite treasure? Would you give me your Koran for such a prize?" You hand over your book and watch as the vagrant stuffs it into a sack and walks away, whistling.</p>
<p><b>No Skill:</b> You should have known better than to trade your piety for wealth. You wander for days looking for a single landmark on the map, but to no avail. By the time you get back to the village, you are dirty and starving yourself. [S1/<em>Scorned</em>]</p>
<p><b>Piety:</b> You follow the directions on the map carefully, tracing the arcane scribbles to a cave hidden under the sand. Inside, you find not only treasures and wonders, but also the beggar. The other claims to be seeking a trusting and pious soul. Handing you back your Koran, the ancient one also offers you a most remarkable object. [S2/<b>Treasure</b>]</p>`,
	},
	2521: {
		index: 2521,
		text: `<p>While you are watering your horse at a small village well, a man dressed in fine robes demands to know your name. He claims to be the local magistrate and accuses you of stealing water from the Sultan's personal well. Apologizing, you beg for forgiveness. The man laughs heartily and asks why you should be spared. You offer to pay for the water you have taken, so it would not be stealing. Eyes averted and thoroughly frightened, you do not notice his grooming does not match his finery.</p>
<p><b>No Skill:</b> Pulling out your most valued object, you see the man's eyes light up. You reluctantly hand over your prize. During the next few days, you begin to wonder and ask about the magistrate. The only response is: "What magistrate?" [S1/Lose one <b>Treasure</b> or W-2 (Min: Poor)]</p>
<p><b>Bargaining and Evaluation:</b> You sift through your many treasures and come across an old ring that you intended to sell at first chance. You pull it out of your bag, treating it as if it was made of spun silver, and extend it carefully upward so as to catch the sun. "This," you say with a touch of awe in your voice, "belonged to a great and powerful sheik. It is said that in the right hands, this ring can raise the dead." The magistrate takes the ring, saying, "That will do. You may go." [D1/S1/Quick Thinking]</p>`,
	},
	2522: {
		index: 2522,
		text: `<p>Exploring the lower reaches of an ancient tomb, you find a robust youth sitting on a glowing sarcophagus in the center of an otherwise bare room. The youth smiles cheerily, "Greetings, fair stranger!" The youth claims to have discovered an enchanted item (patting the sarcophagus) that preserves vigor, at the cost of free will. "I've been here untold years and would be grateful for your help escaping the curse." The youth reaches out a hand and asks that you take it and promises you a sparkling bauble for your help. You agree, and reach out.</p>
<p><b>No Skill:</b> The moment you touch his hand, you find yourself on the sarcophagus, and the youth in your place. Shrugging nonchalantly, the youth apologizes for the deceit and wanders off. [S1/<em>Ensorcelled</em>]</p>
<p><b>Magic:</b> Just before you touch the hand, you notice certain symbolic carvings on the sarcophagus. You withdraw, and cast some protective wards about yourself. You then grab the proffered hand and pull the youth away. Stunned by these events, the grateful person stammers thanks. "Please, take this. It is a small price to pay for my freedom." [D1/S2/<b>Treasure</b>]</p>`,
	},
	2523: {
		index: 2523,
		text: `<p>As you lay on your bedroll, you are surprised to feel something moving inside your tent! Leaping to your feet, you see a slender hand retreat from under the gently moving flap. You run outside and grab the other with a handful of your gold! The young one breaks down crying, explaining that an uncontrollable urge to steal possesses him. Struck by an idea, you propose a way to put that curse to good use: in exchange for a service, you will not turn the thief over to the authorities. The other agrees.</p>
<p><b>No Skill:</b> You take the young one to a nearby village. The local tax collector is an evil man, draining the people of their hard-earned monies and leaving them to starve. You suggest that the other return some of the taxes to the people, starting with you. Unfortunately, the other is caught and executed. [D1/<em>Grief Stricken</em>]</p>
<p><b>Seduction:</b> Smiling coyly, you indicate that a local prince refuses to pay you for a service you recently provided. You had returned a magical treasure to him and he had merely laughed and sent you on your way. You describe the treasure to the thief and ask for its return. The other, entranced by your beauty, heads off to do your bidding. Success! You gain the item and a willing partner. [D1/<em>Beloved</em>/<b>Treasure</b>]</p>`,
	},
	2524: {
		index: 2524,
		text: `<p>Exploring some ruins, you lose your way among the winding passages. You find yourself in a painted chamber, images of a glorious young man and woman on the walls. They appear to be trapped in an endless void, surrounded by 'efreet. All this is fascinating, but it hardly frees you from your current situation. You call to the heavens, promising all your worldly wealth for an escape from the lonely rooms. Suddenly, the handsome couple appears before you, asking if you meant what you said. You reassure them that you will keep your bargain.</p>
<p><b>No Skill:</b> They lead you to an exit and you leap through, seeking to avoid payment. You find yourself alone on a dune, far off in the desert. [S1/<em>Ensorcelled</em>]</p>
<p><b>Wisdom:</b> You follow the couple to an exit and offer up your treasures. You realize it would be foolhardy to attempt to cheat them. They take only a bit of your wealth and bless you. [D1/W−1 (Min: Poor)/<em>Blessed</em>]</p>
<p><b>Piety:</b> When the couple leads you to an exit, you fall to your knees and praise Allah. Your heartfelt words dissolve the bonds holding them in place. Grateful, they refuse to take your belongings and instead award you with a treasure. [D1/S2/<b>Treasure</b>]</p>`,
	},
	2525: {
		index: 2525,
		text: `<p>Cresting a hill far from any town or village, you see the other sitting on a stone. The other has been lost for many days, and wonders if you can help. The other can offer only the stories of their adventures as repayment. You sit and listen.</p>
<p><b>No Skill:</b> The other's tales are wondrous and strange. They are more than adequate to compensate you for your help guiding him back to civilization. [S1/Storytelling]</p>
<p><b>Scholarship:</b> The stories told are so compelling, you must write them down and fill an entire volume with them. You realize that the tales are more than just stories; they are accounts of the other's life. You decide to seek out some of the wonders the ancient one described. You vow to share any treasures that you find with the raconteur. [S2/Draw two <b>Treasures</b>; keep one, discard one]</p>`,
	},
	2526: {
		index: 2526,
		text: `<p>You encounter a young man sitting forlorn in front of his home, a sad bouquet of old flowers dangling in his hand. Sitting down beside him and ask, "So friend, who is she?" He tells you that the daughter of a local tanner has rebuffed his advances, even though her father approves of him. She loves another, the son of the magistrate. You offer this advice: "My friend, if you wish to win her heart you cannot do so with sad gifts and a sad face. You must fight for her love!" He cries out, "Of course! I must FIGHT for her love!"</p>
<p><b>No Skill:</b> He runs off. Sadly, his skill is no match for that of the magistrate's son. He returns home rejected, wounded, and angry at you. [D1/<em>Scorned</em>]</p>
<p><b>Seduction:</b> You smile, "No, my friend, the trick is subtlety. You must woo your love with all the arts of romance. Show her that you are sensitive and caring but strong and protective." You teach him about the fine art of courting a woman. The next morning he returns home and smiles. "Thanks to you, my friend, we are set to be married, and I wish to reward you for your help." [D1/S1/W+1 (Max: Princely)]</p>`,
	},
	2527: {
		index: 2527,
		text: `<p>Crossing the burning sands, you find that your water skin has sprung a leak. Your survival is at stake. Fortunately, you come across an old shack, barely standing. The other dwells within, exiled by sorrow from their homeland many leagues away. The other will give you water, but claims to have no need for money; instead, he asks that you deliver a letter to his estranged brother.</p>
<p><b>No Skill:</b> When you arrive at the brother's home, he accepts the letter but reads it reluctantly. The other has been gone for many years, and this newly delivered expression of regret is insufficient to make up for the years of neglect. The sibling will die alone and unloved. [S1]</p>
<p><b>Beguiling:</b> The brother rejects the letter, unmoved by the regrets expressed in it. You plead on the other's behalf, describing the wretched existence and the sincere love the other holds in his heart. The brother rethinks his harsh feelings and sets out to reunite with his sibling. [D1/S1/<em>Blessed</em>]</p>`,
	},
	2528: {
		index: 2528,
		text: `<p>The other has a remarkable collection of swords, one of which you desire greatly. After much haggling, you cannot agree on a price—until finally the other issues a challenge: defeat him in combat and the weapon you seek will be yours as a gift.</p>
<p><b>No Skill:</b> You accept the challenge and, to no one's surprise, the other beats you easily. "You are not worthy of such a fine weapon—I suggest you pick up a stick." That said, the other turn his back on you. [<em>Scorned</em>]</p>
<p><b>Weapon Use:</b> You accept the challenge and the duel begins. In a matter of seconds, you realize that never before have you seen such display of skill and confidence. Even though you hold your own, you know you cannot hope win. Drawing back, you place your sword on the ground and compliment the other profusely on his skill. To your astonishment, the other hands you the sword you sought. "The blade is a tool not of the arm but of the heart, and of the mind. You are wise enough to know when the battle is lost; this will help you when the battle can still be won." [D1/Weapon Use]</p>`,
	},
	2529: {
		index: 2529,
		text: `<p>The other will accept nothing less and asks nothing more than the time required to master his teachings. It will be a long and tortuous process, but the reward will be well worth it.</p>
<p><em>Do you accept his terms?</em></p>
<p><em>No:</em> You continue on your way. [S1]</p>
<p><em>Yes:</em> You remain for many weeks learning all you can from this master. [Remain in this space for the next turn, drawing no encounter card. At the end of that turn, gain both Weapon Use and Enduring Hardship]</p>`,
	},
	2530: {
		index: 2530,
		text: `<p>Above all else, the other craves knowledge, but do you have what he needs?</p>
<p><b>No Skill:</b> Unfortunately, you don't. The other is disappointed, but he is willing to teach his skills but offers an outrageous sum.</p>
<p><em>Do you wish to spend three wealth levels?</em></p>
<p><em>Yes:</em> The other is an excellent teacher. [W−3 (Min: Penniless)/Weapon Use]</p>
<p><em>No, or you do not have Wealth of Rich or greater:</em> You respectfully decline his terms, and he goes on his way. [S1]</p>
<p><b>Storytelling, Scholarship:</b> You immediately begin to discourse on the skies, and the earth, and the sea, and all the things therein and thereupon, their comings and goings and their beginnings and ends. The other drinks in your stories like a traveler long stranded in the desert upon finding a deep, cool spring. He shares with you stories from his own long, adventurous life. [D1/S1/Storytelling]</p>`,
	},
	2531: {
		index: 2531,
		text: `<p>The other seems flattered by your reaction and invites you to join in a meal beside the campfire. You laugh together, trading stories long into the night, and when you awake the next morning, you find your purse missing. Also missing are your camel, sword, and most of your personal possessions.</p>
<p><b>No Skill:</b> You stumble to the nearest village, a bedroll all you have to your name. You find charity at a local home, but soon you must continue on. [S1/W−4 (Min: Penniless)]</p>
<p><b>Wilderness Lore:</b> Tracking a person through the desert is so much easier when they are burdened with more than they can carry. You catch up to the traitor and ask for your belongings back in exchange for some of the water you have with you. They readily agree and beg your forgiveness. [D1/Piety]</p>
<p><b>Stealth and Stealing:</b> Giving chase, you find the thief the next night sitting by a fire, eating your food and reading your personal letters! Come the morrow, though, they find themselves stripped of not only all your goods, but their own meager possessions as well! [D1/S1/W+1 (Max: Respectable)]</p>`,
	},
	2532: {
		index: 2532,
		text: `<p>Traveling one night, you hear the distant sounds of someone screaming. As you rush to investigate, you crest a dune and see four men surrounding a young woman. You draw your sword and shout, hoping to scare them off. Instead they turn and grin at you, the woman included. It was a trap! From all around come more bandits. They take you to their leader, whom you immediately recognize as a successful merchant from a nearby city. Thinking on your feet, you play to his famous ego, telling him how impressed you are to meet him.</p>
<p><b>No Skill:</b> He laughs at you and quickly relieves you of your belongings. However, he does decide that you may join his band for awhile, to prove how much you worship him. [D1/S1/Stealth and Stealing/<em>Outlaw</em>]</p>
<p><b>Storytelling:</b> He takes a liking to you. He tells you that the drab life of a merchant has paled, and he has decided to add spice to his life with nefarious deeds. You encourage him, saying that with his skills and acumen, he could become a legendary bandit. He decides that perhaps you may serve his reputation more as a tale-weaver than a victim, and he hires you to tell his stories far and wide. He warns you that unless he is properly famous, he will consider the bargain forfeit. [S2/<em>Under Geas</em>]</p>`,
	},
	2533: {
		index: 2533,
		text: `<p>As you walk through a large, bustling village, trying to sell your wares, you are grabbed by a meaty, sand-scarred hand. That hand is attached to a large man, who has at least three friends behind him. Confused, you are dragged in front of a local merchant, a slovenly, brutal man. "So this is the famed traveler of whom I have heard so much about? Well, we have rules here and you need a license to sell merchandise in this town. What have you to say for yourself?"</p>
<p><b>No Skill:</b> You begin to stammer and stutter, then bow down in abject apology. After a few moments of this, the merchant leans back. "I don't think he will cause us any more trouble. Remove him from my sight!" The thug who brought you here now tosses you ignobly into the dusty street. [D1/S1/Luck]</p>
<p><b>Courtly Graces:</b> You bow down in a show of respect and play to the man's ego. He shakes his head in disbelief, "So you think you can sway me with sweet words and hollow praise? Well, let's see if a few months working in the mines doesn't whittle your tongue!" [D1/Enduring Hardship/<em>Imprisoned</em>]</p>`,
	},
	2534: {
		index: 2534,
		text: `<p>The burning sun hammers against your skin as you cross the desert. You come across a small oasis and are enchanted by the clear waters. Just as you are about to drink, the other comes into view and says, "This pool is cursed. My caravan stopped here months ago for refreshment and I am the only survivor."</p>
<p><b>No Skill:</b> Respectful, but disbelieving, you say, "I am grateful for your service, but surely you are mistaken. The waters look harmless." You drink deeply and move along. Over the next few days, however, you become more and more paranoid. [D1/<em>Insane</em>]</p>
<p><b>Wilderness Lore:</b> You pause and notice that the pool is surrounded by a rare herb that brings delusion and madness! The roots of the purple-flowered plant reach deep into the watery pool. You bow down to the merchant and praise his service, offering some of your scant supply of clean water. He accepts gratefully. Now that you have pointed it out, he recognizes the herb, and knows a fistful of it will bring a great price in the nearest town. [D1/W+2 (Max: Rich)]</p>
<p><b>Piety:</b> You respect this wretch's sense of duty to others. "Praise Allah for your service." You kneel down to pray, then offer the man a drink from your own nearly empty water skin. When you rise to leave, he reaches into her robes and produces a strange powder. "It comes from the plant that poisons the water. Use it wisely," he says. [D2/<b>Yellow Kohl</b>]</p>`,
	},
	2535: {
		index: 2535,
		text: `<p>You are wakened in the middle of the cool night by a sound outside of your tent! Someone is moving around your camp. You draw your scimitar, step out, and accost the stranger. A young man stands there, proud despite his ragged and emaciated appearance. He demands sustenance and a place to rest. You spy an air of nobility about him, and decide to honor his request. After a meal, the man reveals that he is a merchant from a highborn family but has lost his entourage and his way. If you lead him to a nearby settlement, he will reward you.</p>
<p><em>Roll two dice, adding one each for Acting and Disguise, Appearance, and Beguiling. Add two for Courtly Graces:</em></p>
<p>❖ 2–4: The merchant is appalled by your crass behavior as you travel together. He decides that you are not fit for polite company. Perhaps a few years in the mines will teach you manners! [S1/<em>Imprisoned</em>]</p>
<p>❖ 5–10: You pass a pleasant several days together as you travel. At the next town, he proves true to his word and rewards your aid. [D1/S1/W+1 (Max: Rich)]</p>
<p>❖ 10+: The merchant is enchanted by you. Upon reaching civilization, he lauds your grace and bearing. He offers you fine accommodations and shows you his excellent library. You are free to stay and study for as long as you wish. [D1/S1/Scholarship/<em>Respected</em>]</p>`,
	},
	2536: {
		index: 2536,
		text: `<p>As you relax under a tall palm on a particularly warm afternoon, the other approaches you in the shimmering heat. He is obviously thirsty and hungry, and you have plenty of figs and water in your pack. You offer him some, and he draws up short. "Have I fallen so far that I must accept charity? No! Instead, I ask that you consider this an investment."</p>
<p><b>No Skill:</b> You smile and give the man a large handful of figs and as much water as he can drink. "The well-being of all men is the greatest investment," you say, and go on your way. [D1/Piety]</p>
<p><b>Bargaining and Evaluation:</b> You are impressed by the man's bearing even in a hard situation and talk further. Before the day is out, you are business partners—and he is every bit as good as your first impression lead you to believe. [D1/W+3 (Max: Rich)]</p>`,
	},
	2537: {
		index: 2537,
		text: `<p>Looking up at an abandoned temple, you see a crazy man jumping up and down on the slippery dome. You call to him, warning him of the danger. Although panting and clearly exhausted, he does not stop. He claims that Allah wishes him to dance, so dance he will.</p>
<p><b>No Skill:</b> A wise man does not come between another man and Allah. You move on with nothing but a strange tale to tell. [D1/S1]</p>
<p><b>Enduring Hardship:</b> You can think of nothing that will convince this fool to cease, so you climb up and dance with him. Maybe Allah will gaze upon the two of you and have pity on this poor restless man. After three days and nights, Allah returns the man's senses and he is freed of his affliction. [D2/<em>Blessed</em>]</p>`,
	},
	2538: {
		index: 2538,
		text: `<p>While you shop in the bazaar, a dark and mysterious vendor offers you a magical flute for a princely sum. You reach for your purse, the other comes over and smacks your hand harshly. "Do not buy such junk! That scrap is no more magical than the corns on my toe!" The merchant shakes his head, "Pay that one no mind—madness claimed him long ago." But there is something in the other's words that makes you believe it.</p>
<p><b>No Skill:</b> The vendor curses at you and gathers up his blanket of goods in one fell swoop. The other laughs and says, "Good choice, my lad. If you want something magical, this will serve well." [S1/<b>Copper Drum</b>]</p>
<p><b>Scholarship:</b> You look more closely at the instrument, and find it is indeed a cleverly made forgery. The vendor bows deeply, "I can see you are a learned man, I should not have tried to pass off a copy." He produces a shiny bauble from a hidden pouch. "Perhaps something genuine might interest you?" You glance at the other, who nods approvingly. You haggle for a moment, and walk away with your newfound treasure. [D1/Bargaining and Evaluation/<b>Treasure</b>]</p>`,
	},
	2539: {
		index: 2539,
		text: `<p>Late at night, you arrive in a small village. As you make your way through the dark streets, you notice a young couple hastily climbing out of a window. The man implores you, "Please sir, we are young lovers whose families have betrothed us to others. If you call out we will be caught and forced to marry ones we do not love." These two are foolish to ignore the wishes of their elders, but who can fault true love? They depart, but you are soon confronted by two armed men who demand to know if you have seen their children.</p>
<p><b>No Skill:</b> You stammer for a moment, then feign ignorance. Something in your manner reveals more than you intended, though, and the men hurry off in the same direction as the couple. [D1/<em>Fated</em>]</p>
<p><b>Wisdom:</b> You distract the two with a tale of two lovers, destined to be forever separated. The prince, given a fine wife, grew old with many strong sons but remained unhappy even unto his death. The tale of the princess was sadder still, for the loss of her love rendered her barren. Her line died out and their house fell into chaos. The men, entranced by your story, listen for half the night. In the end, they return home, vowing to consider their children's wishes. [S2/Storytelling]</p>`,
	},
	2540: {
		index: 2540,
		text: `<p>When you saw the kindly one sitting on a cushion at the inn, you were intrigued. "Might I accompany you during your evening meal?" In conversation, you learn that the other's children are greedy and were planning to take over the world. The other mentions magical artifacts, the service of a dozen jinn and 'efreet, an army of children warriors, and something called a "Derobulator." The only way to prevent this horrible future is to make sure that the other's considerable wealth is kept out of the hands of the children. The comely one suggests that the two of you marry, so that you would control the fortune. You decide to aid this poor suffering mad one.</p>
<p><b>No Skill:</b> You marry. The children see this as a corrupt ploy to gain wealth on your part. Soon the entire region knows of your money-grubbing deception. [D1/W+1 (Max: Rich)/<em>Scorned</em>]</p>
<p><b>Beguiling:</b> Luckily, you were blessed with more than your share of charm. Despite their misgivings, the other's children cannot help but like you, and you them. When the sad day arrives that the other passes on, you donate the money to the local mosque, and receive a blessing in return. [D2/S1/<em>Blessed</em>]</p>
<p><b>Married</b> (mandatory): You tell the other of your dear spouse, awaiting you at home, and instead connive together with the other a most wondrous scheme that will show the children the folly of all those who crave power more than love. In the end, the children are chastened and rededicate their energies to the benefit of their family and all around them. [D1/S1/<em>Blessed</em>]</p>`,
	},
	2541: {
		index: 2541,
		text: `<p>You have loved another for many years but are too ashamed to admit it. One day, you find that your love has been ensorcelled by a magician. You vow to break the enchantment so you can finally express your true feelings.</p>
<p><b>No Skill:</b> You arrive at your love's home and proclaim your devotion. You denounce the magician as an evil manipulator. Your love laughs at you, and you walk away with nothing but a curse to mark your folly. [S1/<em>Accursed</em>]</p>
<p><b>Magic:</b> You follow the magician and your love, studying their interactions. You discern a flaw in the magician's spell. With further research, you discern the proper counter-incantations and slowly break down the enchantment. When your beloved is free of the mental duress, you appear, explain your actions, and confess your love, which is immediately returned tenfold. [D1/S1/<em>Married</em>]</p>`,
	},
	2542: {
		index: 2542,
		text: `<p>While visiting a relation who is suffering in a home for the sick, you became smitten with another patient. The administrator tells you, "Many years ago this one came to the town, speaking of a lost treasure deep in the desert that was guarded by a horrific beast. The beast, it seems, took a part of this one's soul. You are the first to have inquired about the mad one. Perhaps you could help find a cure." You agree, and sit down to get to know the other. In time, you hear the complete story and come to have true feelings for this poor unfortunate.</p>
<p><b>No Skill:</b> In the end, the madness is complete and there is nothing you can do. Despite your affection, you must leave to live your life. [D1]</p>
<p><b>Scholarship:</b> Speaking with the other methodically, you begin to understand that whatever happened out there, it must be cured out there. You convince the administrator to allow you to take the other to confront whatever caused such distress. Once outside, the other leads you on a fantastic adventure involving trapped tombs, a monster with six arms, and a glorious treasure. The other is indeed cured and you are enriched. [D1/S2/<em>Beloved</em>/<b>Treasure</b>]</p>`,
	},
	2543: {
		index: 2543,
		text: `<p>The Sultan's court is full of many wondrous things—foods from all corners of the known world and experiences that would impress even the most jaded of adventurers. None of this, however, compares to the emerald-eyed beauty you saw dancing among a band of holy dervishes visiting the court. Over the next days, you could not get this one out of your mind.</p>
<p><b>No Skill:</b> You ask around every temple and mosque in the area, but to no avail. No one seems to know of this wondrous creature who danced among the ascetics. [D1/<em>Love Struck</em>]</p>
<p><b>Acting and Disguise:</b> Realizing that no one would tell you where to find the object of your affection if you were to ask directly, you masquerade as a member of the order and join their rituals. Soon you find the one you seek and you profess your love. The other is moved, and teaches you to achieve ecstasy in movement. [D1/S1/Piety]</p>`,
	},
	2544: {
		index: 2544,
		text: `<p>Watching the Sultan, you see something is amiss. Usually a kind and mirthful man who cares so deeply for his people, he acts distant and distracted. By subtle questions, you learn that his favorite child has left the city to join a band of dervishes in a life of ascetic contemplation. Wanting to deliver the Sultan from his heartache, you head off to find this wayward child. When you see the youth, dancing among the holy ones, you are entranced. You must tell the other how you feel.</p>
<p><b>No Skill:</b> You are insufficiently holy, pleasing to the eye, or interesting. Your advances are rebuffed. [S1]</p>
<p><b>Seduction:</b> You please the other and your pleasure is returned in abundance. Now, you must decide how to inform the Sultan. . . . [D1/S1/Beguiling/<em>Beloved</em>]</p>`,
	},
	2545: {
		index: 2545,
		text: `<p>Falling in with a band of dervishes, you come to know and respect them. Their holiness and lack of material desire is refreshing. Among them is one other who draws your eye. You are smitten.</p>
<p><b>No Skill:</b> Although kind, the other does not return your affections. [D1]</p>
<p><b>Storytelling:</b> As you get to know the other, you spin tales of your adventures. You speak of strange events, lessons learned, friends made and lost. Throughout, you note the humbling and uplifting presence of Allah in all that transpired. The other, and indeed all the dervishes, are enraptured by your stories. [D1/S1/Piety]</p>`,
	},
	2546: {
		index: 2546,
		text: `<p>You are approached by a dark stranger bearing the royal sigil of the prince of this land. It seems that the prince's favorite wine-merchant has been kidnapped and taken to an old mosque hidden in the mountains. The stranger asks that you retrieve him. When you arrive at the distant valley, you find the merchant sitting among a dozen holy men. Seeing your bewilderment, the other tells you that he fled his old vocation to follow Allah's calling.</p>
<p><b>No Skill:</b> You have promised the prince that you will bring the man back. When he refuses to come along, you toss a sack over his head. He has responsibilities, and you do not have the right to forgive him of them. [S2/Lose Piety]</p>
<p><b>Beguiling:</b> You make the man an offer. In exchange for his return with you, you will act as advocate for his religious calling. He reluctantly follows you, but when you arrive, he is immediately locked away for betraying the prince's service. A courier hands you your reward and thanks you for your assistance. [D1/S1/W+2 (Max: Rich)]</p>`,
	},
	2547: {
		index: 2547,
		text: `<p>Traveling through a small, poor village, you hear children moaning and crying. In a rundown shack you discover a mother whose three children are dying of some unknown disease. You seek out the local seller of herbs and medicines, who is as poor as the other villagers. He informs you that the mother is an adulteress and it would not be proper to assist one such as her. You beg Allah for forgiveness and knock the old man him unconscious and carry him and his wares to the hut. There, you explain that you will care for the children.</p>
<p><b>No Skill:</b> Angered, he begins to work, applying salves and boiling teas. You wait here a few days to see if the cures work, and they do! The healer comes to you later and apologizes for his selfish behavior. [D1]</p>
<p><b>Magic:</b> Watching him, you realize the old man aids his herbal remedies with magic. You quietly whisper, "If your magic harms these children, my judgment will be swift." The other sighs and continues to work, but his gestures change slightly. Soon the children are bright and alert! The merchant curses you, "I hope you live a thousand months, and not one brings you even a faint joy!" [D1/S1/Magic/<em>Accursed</em>]</p>`,
	},
	2548: {
		index: 2548,
		text: `<p>While traveling a lonely desert road, you come across the ruins of a caravan which has been destroyed by bandits. In the wreckage, you find only one survivor, an old trader in tattered robes. His legs are shattered, and it is clear he is dying. "I spent everything I have to win this bauble," he says, showing you a great ring. "But now I will die before bringing it to my mother. I would have you bring her to me." You realize that he will not likely survive long enough for you to complete a round trip, so, despite his protests, you haul him up onto your mount and ride to the nearest town. When you arrive, you quickly find the mother's house.</p>
<p><b>No Skill:</b> As you reach the house, the old woman come running out. She leans in close to her son and they whisper for a moment before he passes. She turns and spits at you, "Curse you for moving him. You have killed my son!" [D1/<em>Accursed</em>]</p>
<p><b>Luck:</b> The young man brightens at the sight of his mother. "Mother, I have brought you a present!" He places something in her hand and then breathes his last. She tosses the object in the dirt. "I do not need this horrid prize! I warned you not to seek such blasphemous things!" You pick up the object and place it deftly into your pack. [S1/<b>Seal Ring</b>]</p>`,
	},
	2549: {
		index: 2549,
		text: `<p>You take advantage of a cool, clear night to cross the otherwise inhospitable desert. Up ahead, you see the light of a campfire and the raucous sounds of men drinking. Sneaking closer, you see five bandits laughing and drinking and tormenting a thin youth. Although the youth wears threadbare clothes and is coated in dirt, you recognize the child of a local sheik. You decide you cannot leave this wretch to such a fate.</p>
<p><b>No Skill:</b> You wait until the youth is out of earshot of the men and make your presence known. Surprised, the youth yelps. The bandits investigate and you flee. They catch and thrash you. [S1/<em>Wounded</em>]</p>
<p><b>Weapon Use:</b> Drawing your weapon, you charge the drunken men and scatter them. You seize the youth and run off into the night. When you pause, the young one explains, "I am sorry, sir, but I must return. I have been chosen by Allah to help these criminals to see the error of their ways." With that, the youth walks back toward the camp. [S2]</p>
<p><b>Stealth and Stealing:</b> You slip into the camp undetected and slide your hand over the young one's mouth. Lifting the tormented one from the ground, you dash off into the night. You escape but hear shouts of anger, vowing to chase you to the ends of the earth. Grateful for your actions, the pious one teaches you the art of disguise. [D1/S1/Acting and Disguise/<em>Pursued</em>]</p>`,
	},
	2550: {
		index: 2550,
		text: `<p>While walking in a small market, you notice the other. Something in the other's behavior catches your attention and you realize the other is not what he seems, but is a villain in disguise. You sneak up close to the other, holding your sword to his back, and draw him down a dark alleyway. He smiles and pushes open his cloak, revealing leather armor and a pair of daggers. You look up and see several large men in the alley.</p>
<p><b>No Skill:</b> "You played your part perfectly," she mocks. "I am continually amazed by the stupidity of would-be kidnappers." The men hold you as she relieves you of your belongings. [D1/W−2 (Min: Poor)]</p>
<p><b>Quick Thinking:</b> You spring aside and spin your sword through a series of complex motions. Your movements are flawless and impressive. One of the men pales, "We have bearded a sword master. Let us flee before he carves us like baked sheep." After they depart, you inform the local magistrate of the scam and are rewarded. [S1/W+1 (Max: Respectable)]</p>`,
	},
	2551: {
		index: 2551,
		text: `<p>When you arrive in this small town, the only thing on all lips is the reward being offered for the capture of a notorious criminal known to be in this area. You have seen one who matches the description among a band of ruffians camping in a ravine as you came here. You head off and are fortunate to find the men still there. In time, the one you seek wanders into a small copse to relieve himself in privacy. Sneaking up, you place your sword to the back of his neck, saying, "Come with me quietly." As you lead him away, he explains that he is not, in fact, a bandit, but is the other, disguised for his own purposes.</p>
<p><b>No Skill:</b> You decide to let the local magistrates sort truth from fiction here, and deliver your captive for the reward. [D1/W+1 (Max: Respectable)]</p>
<p><b>Acting and Disguise:</b> You recognize the skill of the disguise, and ask the other his story. The bandits, it transpires, slaughtered the other's entire family in a raid. The other swore justice and infiltrated the band. By cunning means, he eliminated all their leaders, leaving only the weak and foolish; the "reward" was his own plan, to secure his role in the group. You are impressed by the audacity of the other's plan and assist the other in completing his plan. [D2/S1/Stealth and Stealing]</p>`,
	},
	2552: {
		index: 2552,
		text: `<p>Visiting a relative's home, you are surprised when a troop of soldiers burst in and arrest the homeowner for murder! You console the family and plead before the local magistrate, but to no avail. On the day of execution, you infiltrate the guards while the family causes a distraction. Spiriting the other away, you both flee into the desert.</p>
<p><b>No Skill:</b> The desert is a harsh place. You are unable to keep your relative alive during the long trek. You have done the family little good. [D1/<em>Pursued</em> (SOLDIER)]</p>
<p><b>Enduring Hardship, Wilderness Lore:</b> The two of you do not stop until you are far into the hills east of your village. Although life is hard, you both survive. In time, your relative, who is a scholar, explains that if certain books can be secured from the family's home, you may be able to clear her name. You sneak into town and find the volumes. Later, you both appear before the magistrate and cite an obscure law that allows a person with family who performs a pilgrimage to Mecca to offer a goat to stave off punishment for a crime. In this way, your relative is freed. You, however, are guilty of helping a prisoner to escape. You flee back into the desert. [D1/S1/Stealth and Stealing/<em>Outlaw</em>]</p>`,
	},
	2553: {
		index: 2553,
		text: `<p>It was a magnificent device, brass and slender. Through one end, you could see the far end of the market up close, as if by magic. As you handled the tube, sun flashed on its polished surface. This startled a nearby horse, which bolted, pulling its loaded cart behind it. The cart tore away from the harness and slammed into the soft mud wall of the jail. The wall came crashing down, and from inside streamed more than a dozen prisoners! You walked off casually, hoping no one had seen the cause of the commotion. Later, one of the prisoners cornered you in an alley. She threatens to report your actions if you did not help her escape the town. "Look over there!" you yell, then knock the woman unconscious and sling her over your horse.</p>
<p><b>No Skill:</b> You carry the woman back to the jail, dumping her in a nearby alley. Then you quickly leave town. [S1]</p>
<p><b>Beguiling:</b> You return the unconscious woman to the jail, explaining that you—a coincidental witness to the accident—caught this woman trying to escape. You warn them you have struck her quite hard on the head, so she may be delirious when she awakens. You caution the guards not to believe any of the nonsense she spouts. You claim a modest reward from the guards and head off on your way. [D1/W+1 (Max: Respectable)/Quick Thinking]</p>`,
	},
	2554: {
		index: 2554,
		text: `<p>Sitting in a local inn, you overhear the most amazing tale! A man has captured a beast marked by Allah. It is rumored that the beast was once human, a woman who found the lost treasure of the Sultans, and was transformed into animal form as punishment. The beast is imprisoned at a local sheik's manor, as scholars attempt to lift the curse and discover the location of the treasure. Without a moment's hesitation, you travel to the sheik's house. You scale the wall and steal into the courtyard. You find the beast trapped in a magical cage with a golden lock. Hushing the whining beast, you pick the lock and open the cage door. Suddenly the lock itself begins to scream!</p>
<p><b>No Skill:</b> You toss your rope over the animal's neck and drag it away as the guards approach. In the struggle it bites you. Around the bite, your skin begins to grow a thick pelt. . . . [S1/<em>Beast Form</em>]</p>
<p><b>Bargaining and Evaluation:</b> You quickly realize that even if you did manage to drag this huge beast off in time, you have no way of removing the curse. This lock, however, might just fetch a pretty penny. Muffling it in your cloak, you depart. As soon as it quiets, you sell it. [D1/W+1 (Max: Rich)/Stealth and Stealing]</p>`,
	},
	2555: {
		index: 2555,
		text: `<p>The one you have been pursuing for months is quite fetching. Finally, he relents and promises you his heart, but warns you that her brother, a greatly respected holy man, has sworn never to let his youngest sibling marry without his permission, and his standards are so high that none shall ever meet them. Your lover tells you where to find the other, and you head out to threaten him.</p>
<p><b>No Skill:</b> You find the holy man easily, taking him to a secluded alleyway, and a blade to his throat makes him agree to bless whomever his sibling loves. After you return to tell your lover the great news, you find him in the arms of another! You were played like a fish on the line. [S2/<em>Grief Stricken</em>]</p>
<p><b>Seduction:</b> "There is no need to dispose of your former lover," you tell him. "Your love will protect us forever." You sweep her into your arms and kiss her deeply. [D1/<em>Beloved</em>]</p>`,
	},
	2556: {
		index: 2556,
		text: `<p>Riding into a valley, you hear drums coming from nearby. Curious, you investigate and see a town. Atop a high building, men in red robes and turbans are executing men in chains. By their garb, you realize they are a band of dervishes. They refuse to cry out in terror! Gathering your strength, you race up the tower and grab the oldest of the dervishes and leap off to a nearby rooftop. The dervish quickly explains how the Magians came and ensorcelled the townsfolk, while you look for a way to the ground.</p>
<p><b>No Skill:</b> The only way down is a drop five times the height of a man, which would surely kill the aged dervish. The other insists on staying behind. "Go and bring us freedom; I will die with my fellows." You return days later with a band of soldiers, and find no survivors in the town. [D1/S1/<em>Grief Stricken</em>]</p>
<p><b>Quick Thinking:</b> Directly below you there is the roof of a slave barracks. With the help of the dervish, you free the two dozen men within and arm them with shovels and axes and charge the tower. With each guard your mob brings down, you gain a sword, and soon you overwhelm all the Magians and free the town. [D2/S2/Piety/<em>Respected</em>/<b>Robe of Honor</b>]</p>`,
	},
	2557: {
		index: 2557,
		text: `<p>You have encouraged the people of the town to hold a feast in the honor of the other and made sure that you are seated near him. Unnoticed, you put <em>benj</em> in his drink, and when he passes out, you remark that you are a physician and will see to his well-being. You whisk him away to a private abode before anyone becomes suspicious.</p>
<p><b>No Skill:</b> The other is held in such high regard that you are easily able to ransom him for a substantial sum. You must leave immediately with your ill-gotten gains. [W+2 (Max: Rich)/<em>Outlaw</em>]</p>
<p><b>Beguiling, Courtly Graces, Scholarship:</b> You appear before the townspeople and are able to convince them that the other has died. You even display the other's body, the pallor of death on his skin a ruse of your devising. You say that with your secret knowledge, you can save the other even from death, and by secretly administering an antidote to the <em>benj</em>, the other rises from his "deathbed"! You are showered with gifts by the grateful people of the town, who truly believed he had died. [S1/W+2 (Max: Rich)/<em>Respected</em>]</p>`,
	},
	2558: {
		index: 2558,
		text: `<p>You have come up with a scheme to make the object of your affections: you will feign a duel with a renowned soldier who is passing through town, to make yourself look heroic. You approach the other, but he wants no part of your plan. Infuriated, you slip a little <em>benj</em> in his drink and, when he starts to fade, you pick him up and lead him to the town square. You whisper, "Make it look good and there's double the coin in it for you."</p>
<p><b>No Skill, Accursed</b> (mandatory): Even drugged, the other is far your superior. With but a single blow, he sends you reeling across the town square. He turns on his heel and staggers off, leaving you in shame. [S1/<em>Scorned</em>]</p>
<p><b>Weapon Use, Magic:</b> The other leaps to the attack, and you are hard-pressed to keep up. If you had not drugged him, he probably would have defeated you! In the end, you knock him to the ground. There can be no glory in such a victory, though. [D-1/Lose <em>Respected</em>]</p>`,
	},
	2559: {
		index: 2559,
		text: `<p>Somewhere in the Sultan's royal library lays the answer to a riddle you found scrawled on the back of an otherwise inscrutable map. The question is, how do you get in? You sit outside the building for days, careful not to be seen, studying the place. There is a soldier standing guard outside—if you can but remove that threat, you would have an easy time of it. You learn the soldier's daily routine and soon it becomes child's play to isolate and abduct the target. Later on, as you take his place, you confront the Royal Librarian. Under threat, the librarian uses magical keys to gain entrance to the library, and even aids your research. Lost in your work, you fail to notice as the librarian illuminates a number of lamps. The Sultan's guards cannot help but notice the "closed" library ablaze with light.</p>
<p><b>No Skill:</b> You escape, barely, but lose the map and your research. [D1/<em>Outlaw</em>]</p>
<p><b>Acting and Disguise:</b> You bind and gag the librarian, and shove him in a back room. You don his robes, arrange your hair just so, and dim a number of lamps. When the guards arrive, you stay in the shadows and wave them off dismissively. In a rough voice, you claim that the Sultan has demanded that you perform important research. The soldiers leave you to your work. You depart swiftly before they return. You learn no secrets but neither are you jailed . . . or worse. [D1/S1/Quick Thinking]</p>`,
	},
	2560: {
		index: 2560,
		text: `<p>Through a series of misadventures, you fall into the debt of a pirate captain. He comes to you and demands that you convince a famed swordfighter to join his ship's crew. The warrior will not be easy to convince, and you cannot hope to win through force of arms. The pirate recommends you resort to abduction, but has little more advice to offer. He chuckles as you depart. You despair of completing this task, but you dare not risk the pirate's wrath. You locate the weapon master and plot your approach.</p>
<p><b>No Skill:</b> You speak with the fighter, telling the truth and pleading for understanding. You appeal to the other's sense of adventure. The swordfighter scoffs at you, slashes your arm for your temerity, and sends you packing. [S1/<em>Wounded</em>]</p>
<p><b>Enduring Hardship:</b> It is clear you cannot take the warrior by force, so instead you rely on guile. You "happen upon" the fighter and offer to buy drinks in exchange for stories. Through sheer intestinal fortitude, you are able to keep your head when the other drops unconscious. You drag his limp body to the pirate ship and settle your debt. [D1/S1/Wisdom]</p>`,
	},
	2561: {
		index: 2561,
		text: `<p>When you broke into the merchant's house, you believed no one to be home. After all, the daughter of the household was getting married at the other end of town. Who would miss that? Well, it turns out her brother would. He was against the marriage and refused to sit through the farce! You were midway through cleaning out the jewelry case when you heard from behind you, "You'll pay for your crimes, villain." Ducking quickly, you avoid the man's attack. Striking out, you knock him senseless. You bundle him up with the loot and ride away.</p>
<p><b>No Skill:</b> You dump the man in a ditch on the way out of town. You cannot bring yourself to kill him, even though his testimony will mark you as a wanted man. [D1/W+1 (Max: Respectable)/<em>Outlaw</em>]</p>
<p><b>Wisdom:</b> As you ride away, you notice a slave caravan preparing to leave town. It costs you a portion of your loot, but when it leaves, it takes with it one more enslaved soul. None will be giving your description to the local magistrate. [D2/Bargaining and Evaluation]</p>`,
	},
	2562: {
		index: 2562,
		text: `<p>A hated rival, and a well-respected warrior, has just been appointed a city magistrate. You are certain that this man will use his newfound power to have you arrested and jailed. Before that can happen, you sneak into his home and abduct him. You ride out into the wilderness, intending to leave the miserable one to his fate.</p>
<p><b>No Skill:</b> In your haste to humble your rival, you failed to pack enough supplies or note your route. You get lost and must rely on your rival to lead you back to civilization. Not only are your plans ruined, you are now in your rival's debt. [D1/<em>Envious</em>]</p>
<p><b>Wilderness Lore:</b> You make your way through the barren landscape, hiding your trail and losing the pursuit. You laugh heartily as you ride off, your rival tied to a dead tree. [D2/Enduring Hardship]</p>`,
	},
	2563: {
		index: 2563,
		text: `<p>Honor demands you accept the challenge of a duel from a hardened soldier. You best the man but still he refuses to allow the matter to drop. He vows revenge and starts spreading rumors about your family and tastes in bed partners. You search him out, knock him senseless, and drag him to a hidden room.</p>
<p><b>No Skill:</b> You beat him until he agrees to retract the vicious statements. You let him go, but he simply tells all of your actions, causing your reputation further harm. [D1/<em>Scorned</em>]</p>
<p><b>Acting and Disguise:</b> You don the guise of a magistrate and bring the man to the docks. You claim to have an order sentencing the man to a long sea voyage. You launch into a litany of the man's many crimes and by the time you are done, the ship captain tosses him in the hold. It will be a long time before the dog sees the light of day. [D1/S1/Storytelling]</p>`,
	},
	2564: {
		index: 2564,
		text: `<p>You spend all day looking for a fresh camel, as your current one has taken ill. The only man who sells them in town seems hesitant, and after a long day of unsuccessful haggling you retire to a smoke-filled inn, where you gradually doze off. Traveling all these nights, however, has trained you to remain aware of your surroundings, and your hand shoots out before you fully wake to grab the wrist of a woman reaching for your coin purse. Your eyes open and follow the slender arm up to the dirty but beautiful face of the young bandit. "Allah does not seem to support your chosen profession. But there is something I can use you for."</p>
<p><b>No Skill:</b> Realizing that neither wealth nor piety will inspire the local herdsman to sell you a camel, you send the thief to beguile the hard man into giving one to you. The thief proves better as a negotiator, and the next morning you ride off on a fresh mount. [S1/<em>Determined</em>]</p>
<p><b>Stealth and Stealing:</b> You take the young thief along with you when you go to commandeer a mount for the next leg of your journey. You teach her a few skills and she travels with you for some time learning your trade. Eventually you release her, and hear nothing from her for many nights. Then one night a messenger arrives for you, carrying a strange package. The note is from your apprentice: "Dear Master, I wish to repay you for all you taught me. I found this bauble that I believe will better fit your pocket than it will mine." [D1/<b>One Hundred Keys</b>]</p>`,
	},
	2565: {
		index: 2565,
		text: `<p>Walking through a dusty village, a woman's voice berates someone about their lack of a profession, and the other yelps in protest as she is tossed into the street to land at your feet in an ignoble heap. Dejected, she looks up at you and Allah inspires you to take pity. Extending your hand, you say gently, "If you would like a job, perhaps I can provide. It may not be a profession your mother imagined, but it might serve you well." With nowhere to go, the other nods compliantly.</p>
<p><b>No Skill:</b> Everyone needs a good camel handler, and the other proves to be better than average. For the next leg of your travel, your camel never seems to tire or become irate. [D1/Enduring Hardship]</p>
<p><b>Quick Thinking:</b> You swing the other onto your camel and begin to ride to the local inn, where they are to act as your valet. Behind you, the sounds of shouting make it clear that others might want to speak to your new charge. It turns out that leaving the village was construed by the constabulary as fleeing, as the young woman was a con artist whose previous professions had led her to hide in her mother's home. As you spur your mount out of town, you think, "This is what I get for acting hastily, but maybe they can teach me a few tricks for my troubles." [S1/Beguiling/<em>Pursued</em> (SOLDIER)]</p>`,
	},
	2566: {
		index: 2566,
		text: `<p>As you lay under a shady date tree, you see two people approaching through the noon haze. One of them is a beautiful young woman, and her interlocutor is, a badly scarred hulk of a man with one missing eye and a noticeable limp. The woman insists that taking care of oneself is the most important thing one can do to live a good life; the other argues that experience and risk make a good life. As they pass, they see you sitting and approach you for your opinion on the subject. You offer them a task to prove whose method is the most effective. Paying them a gold coin each, you tell them of a cave that you had come to investigate nearby in which was said to be a great treasure guarded by an enchantress. Whose methods work to gain you her secret treasure, you judge to be the most beneficial.</p>
<p><em>Roll two dice, adding one for Storytelling:</em></p>
<p>❖ 2–3: They do not buy your story, and consider you a fool for wasting their time. [D1/<em>Scorned</em>]</p>
<p>❖ 4–7: The scarred man returns, holding a valuable treasure glittering in the sunlight. He presents it to you, and you declare him the winner of the contest. [D1/S1/<b>Treasure</b>]</p>
<p>❖ 8–11: The beautiful woman returns, telling you that the story was just a myth. A lonely old herbalist lives in that cave, who was more than happy to have the company of such a nice person. You declare the maiden the winner and visit the herbalist yourself; she turns out to be a skilled healer. [D2/You may lose one status of your choice]</p>
<p>❖ 12+: You wait the entire day and neither finds their way to your lonely tree. As you are about to go investigate, a stunningly beautiful woman appears as if out of a mirage. "You sent your servants to steal from me, and now you shall join them in their fate!" Before you have a chance to react, you find yourself bound by a magical chain and then sold to the next passing traveler [S1/<em>Enslaved</em>]</p>`,
	},
	2567: {
		index: 2567,
		text: `<p>You are approached by a well-dressed man, who boldly sits next to you and tells you a tale of a treasure stolen from him by pirates. Indeed it is a sad tale, but your mind turns to the other treasures these pirates might possess. You ask the man to draw you a map of the last-known location of the pirates and pay him handsomely for it. When you return home with the map and begin plans for your voyage, you find the markings nearly incomprehensible.</p>
<p><b>No Skill:</b> After a month of struggling to make sense of the information on the map, you realize you have wasted your time—and money! [S1/W−1 (Min: Poor)]</p>
<p><b>Seamanship:</b> Your knowledge of the seas allows you to decipher the oddly scrawled map and fills in some information that was intentionally left out to cheat you. When you arrive at the location indicated, the pirates are gone, but their booty remains for the taking. [D2/S1/W+2 (Max: Princely)/<b>Treasure</b>]</p>`,
	},
	2568: {
		index: 2568,
		text: `<p>You encounter a gaudily dressed little man with a slick air. Flamboyantly, he describes himself as a merchant, raconteur, and entertainer. He seeks to accompany you and asks only a pittance in return. Intrigued by his dress and demeanor, you agree. During your travels, he lifts your spirits with his stories, jests, and distractions. Your favorite is an odd game using black chips etched with strange symbols. After a couple sessions, he offers to add spice to the game by wagering on the outcome. Challenged, you accept.</p>
<p><b>No Skill:</b> The enticing game captivates you. After several days, you find you have lost all of your gold. The diminutive rake packs his bags and wanders off. [W−1 (Min: Poor)/Wisdom]</p>
<p><b>Luck, Wisdom:</b> After several games, you begin to see patterns and become more accomplished. In time, through luck or great focus, you notice certain telltale signs on the backs of the chips. The little man is hustling you. You grow angry and accuse him. In response, he laughs and nods. He returns your gold and offers a glowing ring as recompense. [S2/<b>Seal Ring</b>]</p>`,
	},
	2569: {
		index: 2569,
		text: `<p>Your mount falls ill and can no longer carry you. At the next village, an old man with wooden teeth offers to transport you on his wagon for a modest fee, which you accept. During your travels, the man tells you a sad tale. He claims to have once been a wealthy trader beset by bandits, who stole all but his meager wagon and broken-down horse. Indeed, the transport proves less reliable than you hoped. At various points along the way, the wagon breaks or the horse stalls. Each time, he pitifully requests additional sums to buy food or make repairs.</p>
<p><b>No Skill:</b> You warm to the old codger and accede to each request in turn. Feeling good for your act of charity, you do not notice the fine clothing hidden under his cloak, or the bulging sacks in the bed of the wagon. [D1/W−1 (Min: Poor)]</p>
<p><b>Bargaining and Evaluation:</b> "Life is pitiless, old man," you explain. "I myself have recently lost a fine mount. I will pay what we agreed upon, and no more." The codger continues to whine, but you notice that, after each "breakdown," the horse starts up or the wagon continues on even through you have passed him no more money. At the next town, you purchase a camel and gladly rid yourself of this cheat. [S1/Wisdom]</p>`,
	},
	2570: {
		index: 2570,
		text: `<p>During your travels, you have accumulated several belongings. Struggling to carry them, you are approached by a ragged other who offers to help for a few coins. Grateful for the aid, you fail to notice the other's smooth skin and healthy limbs do not match his otherwise destitute air.</p>
<p><b>No Skill:</b> The other follows you with several of your larger bags. As you pause to enter a shop, he sprints off and is lost in the crowd. [S1/W−1 (Min: Penniless)]</p>
<p><b>Wisdom:</b> As you hand over your belongings, you notice the other's hands are insufficiently rough for a day laborer. You arrange your movement about the city to follow a patrol of watchmen. When the disguised thief makes his move, you are ready and shout for the guards. They apprehend the trickster and inform you a reward has been offered for this man. [D2/W+1 (Max: Rich)]</p>`,
	},
	2571: {
		index: 2571,
		text: `<p>Walking into a small village, you find it oddly quiet and empty. Certainly, the shopkeeper appears to have a kind smile, the innkeeper a thin woman, and the stable boy industrious. Still, you realize that you never see more than one person at a time. You grab the next person you see—an old woman selling figs from a street blanket—and she turns out to be a nondescript young man in disguise. He explains that he betrayed the village to an evil Vizier, who rounded up the inhabitants for vile magical experiments. Instead of payment, the man has been cursed to act out the roles of all the dead villagers. Over time, he has developed a great facility with disguises. Amazed by his skills, you offer to pay him to teach you.</p>
<p><b>No Skill:</b> The young man is willing but cannot ignore the curse long enough to teach you. [S1]</p>
<p><b>Magic:</b> Whispering a long incantation, and performing several gestures, you dispel the magic binding him. Overjoyed, he agrees to accompany you, putting his skills to use in your adventures. [D2/S1/Acting and Disguise]</p>`,
	},
	2572: {
		index: 2572,
		text: `<p>You happen upon a young other beside a lonely oasis. Offering the other a gold coin for his services, you ask that he guide you to the nearest village. He agrees and leads you off into the desert. Hours pass, and your young guide walks and walks. Finally, you can take no more and you ask, "How much longer to the village, my friend?" The other turns and smiles a wry grin, "Village?" The rogue explains that he has taken you into the Desert of Death. He might be able to guide you back out again, but it will cost much more than a couple coins.</p>
<p><b>No Skill:</b> With little recourse, you agree. [S1/W−2 (Min: Penniless)]</p>
<p><b>Wilderness Lore:</b> You shake your head. "I believe I can retrace our steps. You'll get no satisfaction from me." When you finally arrive at a settlement, you inform the local magistrate of the man's trickery, and he promises to warn local travelers of the fraud. [D1/S1/Wisdom]</p>`,
	},
	2573: {
		index: 2573,
		text: `<p>Walking along the road, you notice an indolent other lounging by a tree. Barely moving, the youth tells a sad tale. "I am terribly lazy and refused to work to support my family. An old crone happened by and cursed me. I must tell my story to all who pass. I cannot truly live again until someone pays me to perform a task. Do you have a few coins to spare for some service, carrying your satchels, or fetching some water? I beg you."</p>
<p><b>No Skill:</b> Taking pity on the poor wretch, you drop a few coins in the dirt and say, "Fetch me some water." The youth bounds up and does so. [D1]</p>
<p><b>Seamanship:</b> You know just the thing to cure this soul of any lingering laziness. You are aware of house's master who requires able-bodied helpers. You offer a single coin and tell the youth to report to the house. Arriving with him, the master lauds your aid and offers you a "finder's fee." [S1/W+1 (Max: Respectable)]</p>`,
	},
	2574: {
		index: 2574,
		text: `<p>The other, it is said, suffers under a curse for having tampered in the affairs of the 'efreet. If anyone gives the other even a single coin, he must tell you of your future. You cannot resist. The other takes your coin and looks into your eyes to see what is written there.</p>
<p><b>No Skill:</b> The other smiles and says, "You will have a long and happy life." You are pleased to know that, but you cannot help but feel that it would have been nice to learn more details. [D1/Luck]</p>
<p><b>Luck:</b> The other smiles and says, "Truly the Most High has showered you with favor. I cannot say more, but know that what you attempt, you will accomplish. [D1/S1/<em>Blessed</em>]</p>
<p><b>Fated</b> (mandatory): The other shrieks at what he sees and flees into the night. That, you are sure, cannot be good. [D1/<em>Grief Stricken</em>]</p>`,
	},
	2575: {
		index: 2575,
		text: `<p>Studying in the library, you find a tale of an enchantress who lives in a cave by the sea. This sorceress apparently had the ability to twist men's wills according to her whims. The tale was told by someone named Nawfal the Unfortunate. Greedy to know more, and possibly gain this power for yourself, you seek out Nawfal. Finding the ancient one, you offer coins in exchange for a more complete story. Nawfal cannot refuse; the wicked one's curse requires a lengthy recital. You learn a crucial bit of information: the location of the enchantress. Before you set off, you review a number of texts for wards against enchantment.</p>
<p><b>No Skill:</b> With dreams of convincing princes to surrender their treasure or ifrits to give up their magics, you accost the sorceress. Alas, she but waves a hand and all your protections shatter, bringing you under her spell as well. [D1/<em>Ensorcelled</em>]</p>
<p><b>Scholarship:</b> Forewarned is forearmed. The vile hag cannot pierce your wards and is defenseless before your weapons. She grudgingly teaches you many powerful secrets. [D2/Magic/<em>Blessed</em> [1 use]]</p>`,
	},
	2576: {
		index: 2576,
		text: `<p>You have heard the sorry story of a maiden of this town who is being held hostage against the surrender of her brother, a ruthless bandit leader. Her plight moves you deeply, and you approach the magistrate to allow her to work for you instead of rotting in a dungeon; her wages can go to pay the families of her brother's victims. Moved by your compassion, he agrees.</p>
<p><b>No Skill:</b> Within a week, the maiden has escaped and fled to her brother. You are sentenced to serve in her place. [D1/<em>Imprisoned</em>]</p>
<p><b>Stealth and Stealing:</b> You easily note the maiden testing the limits of her bounds. A week after you take her, she escapes, and you follow her directly to her brother's hiding place. During the night, you help yourself to his ill-gained goods, and then for good measure leave a knife in his chest before you move on to another town. [D1/S1/W+3 (Max: Rich)]</p>`,
	},
	2577: {
		index: 2577,
		text: `<p>You have been cast into prison on a false charge of poaching one of the prince's sheep. While awaiting you chance to prove your innocence, you find that you can speak easily with the prisoner in the next room, and you learn that she is accused of sorcery. You ask her why she does not use her skills to free herself, and she explains that she can only use her magic to help others, and only for a price. You talk with her long through the night.</p>
<p><b>No Skill:</b> In the morning, when the jailer comes, you tell him that you are willing to testify all that you have heard from the witch in exchange for your own freedom. He takes you to the magistrate, who records your statement and lets you go free. The witch sends her own greetings after you, though. [D1/<em>Accursed</em>]</p>
<p><b>Courtly Graces:</b> After a few minutes of further conversation, you realize that she is quite sincere in her beliefs, and by subtle means you lead her to reveal many of her secrets. Finally, when you are convinced that she knows whereof she speaks, you toss her a small pearl from your shoes. "Here is your payment." With that, she says a few words and you are standing, free, outside the town. [D1/S1/Magic]</p>`,
	},
	2578: {
		index: 2578,
		text: `<p>Thrown in jail for a crime you didn't commit, you find yourself in a squalid pit. In time, you dig out an iron bar and bend it to form a hook. A young woman, also captive here, finds some buried rope. The two of you agree to pool your treasures and make an escape together.</p>
<p><b>No Skill:</b> The plan goes off without a hitch. You escape into the wilderness. It proves so inhospitable that you must return to town, where you are hunted by the law. [D1/<em>Outlaw</em>]</p>
<p><b>Wilderness Lore:</b> Escaping into the wilderness, you use your talents to survive. Your fellow escapee is not so knowledgeable and, although you do your best, you cannot save her. She perishes in the harsh desert. You hope Allah will forgive you for your failing. [D1/S1/Piety/<em>Grief Stricken</em>]</p>`,
	},
	2579: {
		index: 2579,
		text: `<p>News of the arrest of the other—your cousin—disturbs you greatly—he is accused of murdering a passing dervish. You return home as fast as your camel will carry you. When you arrive, you find your cousin beyond comprehension, gibbering about sorcerers, 'efreet in human skin, and the curse of a thousand buried treasures. You recall a local mad one who has the reputation for speaking in tongues. You attend the other and offer fair payment to speak to your cousin. The words that pass between the two make no sense to you. Still, when they are done the mad one tells you that your cousin murdered an evil sorcerer and that he has been ensorcelled.</p>
<p><b>No Skill:</b> You explain the story to the magistrate, but he is unmoved. Only a significant bribe will return your cousin to his family. [S1/W−1 (Min: Poor)]</p>
<p><b>Bargaining and Evaluation:</b> Armed with this tale, you plead your cousin's case to the local magistrate. Through hard bargaining and reasoned argument, you are able to convince the official your cousin did no wrong. The magistrate brings in a magician who frees your cousin of his affliction. [D1/S1/Beguiling]</p>`,
	},
	2580: {
		index: 2580,
		text: `<p>You hear rumors of one in a nearby town who has learned to speak the language of the birds. You visit his home and find it filled with hundreds of birds, the air rank and the calls a near-deafening din. The other speaks in a mad screech that is barely recognizable as human speech. The other wants you to go out and find a long-lost treasure of which, he says, the birds have often spoken, and offers to split with you equally anything you recover.</p>
<p><b>No Skill:</b> You agree. The other gives you a falcon to serve you as a guide and watcher. You and your new companion set off into the desert with vague directions and a growing sense of unease. After many weeks, the falcon leaves you and does not return. [S1/<em>Lost</em>]</p>
<p><b>Courtly Graces:</b> You recognize, even through the screeching, that the other is a former courtier. You treat the other's requests with the proper etiquette. The other takes a liking to you and agrees to accompany you on the trip. At various crucial legs of the journey, he calls birds from sky, bearing maps, provisions, or a needed tool. With such help, you are ultimately successful. [D1/S2/<b>Treasure</b>]</p>`,
	},
	2581: {
		index: 2581,
		text: `<p>You seek to punish a hated rival, and you have met the other, who will make the perfect instrument of your revenge. The other appears to pass on madness to any who spends too long nearby. For a simple payment— a dozen fruits, a half gallon of flower-water, and a single stuffed eel—the other will sit outside your rival's home and gibber for days on end. Soon your victim will be gnawing at his fingernails and pulling out his hair.</p>
<p><b>No Skill:</b> Unfortunately, there was a flaw to your carefully laid plan: the mad are by their very nature unpredictable. Instead of remaining in one place, the mad one wanders the neighborhood, infecting all encountered. Word circulates that you are responsible for this blight. [D1/<em>Scorned</em>]</p>
<p><b>Acting and Disguise:</b> The trick, you realize, with any mad person is to keep a close eye out. You spend your days following the mad one in various guises. A gesture here, a guiding voice there, and the insane one remains in place, driving your rival mad with seemingly random chicken attacks, wines spilled on his best robes, and howling dogs outside of every window of every room in which he tries to sleep. You also learn a thing or two about discipline and commitment. The time you spend near the mad one, however, also drives you insane. [D1/S1/Enduring Hardship/<em>Insane</em>]</p>`,
	},
	2582: {
		index: 2582,
		text: `<p>You hire the other to accompany you on your journeys. The other is devout, but more importantly is skilled with arms and accomplished in magic. In a short time, you enjoy many triumphs and become close friends. While exploring a strange paper hut that appeared in the desert, you are beset by massive wasps. You escape with a treasure, but as you turn to congratulate your friend, you find the other has been stung.</p>
<p><b>No Skill:</b> There is little you can do. You watch your friend struggle for breath and die slowly in your arms. The treasure is wondrous indeed, but was it worth it? [S1/<em>Grief Stricken</em>/<b>Treasure</b>]</p>
<p><b>Stealth and Stealing, Wilderness Lore:</b> You realize that if your friend is to survive, you must secure an antidote to the wasp's venom. You creep back into the paper house and retrieve some of the strange jelly that collected in pockets around the hive. Carefully you work your way back out and administer it just in time. [D1/S1/<b>Treasure</b>]</p>`,
	},
	2583: {
		index: 2583,
		text: `<p>Traveling through a small village, you find yourself quickly surrounded by ragged children begging for handouts. You dig into your purse to find a few small coins, when you are approached by a group of dervishes. The leader says, "Allah blesses those who practice charity." You feel you understand his hint, and give the alms to the dervishes instead.</p>
<p><b>No Skill:</b> The leader is amused. "No man, no matter how holy he may claim to be, has greater claim to charity than a hungry child." The dervishes hand your coins directly to the children, who race off in every direction. [D1/Piety]</p>
<p><b>Wisdom:</b> You say, "I know that you have foresworn all luxuries, but you know this land and its people far better than I do. Please guide my gifts to those who are most in need." The leader is very pleased by your gesture, and gives half the coins to the children around. "The rest," he says, "will go to the sick and the elderly, in your name." [D2/<em>Blessed</em>]</p>`,
	},
	2584: {
		index: 2584,
		text: `<p>While out walking, you are accosted by a quick youth in shabby clothes, who swings an ornate scimitar. He has heard of your exploits and challenges you to a duel. You you're your eyes about, and see some distance away a giant of a man, clad in the robe of a dervish, swirling a sword around his head and chanting prayers. You rush to the dervish.</p>
<p><b>No Skill:</b> You say, "I will give a sack of gold if you fight in my stead." The giant shakes his head. "With the sword, I invoke the One God. It would be sacrilege to turn it against a man for vanity or gold." You slink back to the youth, who shows you no mercy. Your reputation and confidence suffers. [D1/<em>Envious</em>]</p>
<p><b>Quick Thinking:</b> You say, "That youth has blasphemed against the One God, cursed the name of the Prophet, and sworn to worship fire demons in the ruins of our mosque! Help me defeat him!" The giant narrows his eyes and strides to the attack. While the youth is distracted, you sneak behind him and brain him with a rock. Examining his sword, you find it is most wondrous [D1/S1/<b>Thunderbolt Sword</b>]</p>`,
	},
	2585: {
		index: 2585,
		text: `<p>You must send some money to your family as soon as possible or they will lose their home. You know of one in this town who has his fingers in a great many ventures; his associates in your home town can get money to loved ones far faster than you can travel the distance yourself. All the other asks in return is that you enter the home of the other's greatest rival and steal a book of accounts from him. You agree to do so that very night.</p>
<p><b>No Skill:</b> You are caught sneaking into the rival's home. The anger of the other at your failure is fearsome indeed. [S1/<em>Accursed</em>]</p>
<p><b>Stealth and Stealing:</b> The task is simplicity itself for one of your skill. Not only do you secure the book for the other but when you creep back into his house, you spy him sitting on a wondrous carpet. The other speaks a special word and the rug lifts him into the air! The next night, after you have delivered the book, you return unseen and avail yourself of the carpet. [D1/<b>Flying Carpet</b>]</p>`,
	},
	2586: {
		index: 2586,
		text: `<p>Wandering the city bazaar, you see a small crowd gathered around a burly palace guard. He announces that the prince is seeking guards for his next caravan to the holy city. You think this would be a perfect opportunity to travel in style with an entourage, but since you are a stranger in this city you will need a representative to bring you to the prince. You approach a wealthy other to be that representative.</p>
<p><b>No Skill:</b> The other scoffs at your attempt and brushes you away. [S1]</p>
<p><b>Beguiling:</b> Your words intrigue the other and convince him to act as your representative. You are hired by the prince. You also learn a few things on how to speak to royalty. [D1/S1/Courtly Graces]</p>`,
	},
	2587: {
		index: 2587,
		text: `<p>You wish the other to join with you in a venture that will make you both rich. The other regards you coldly, then orders brings forth a slave. He points cruelly at her, saying "One does not become as wealthy as I have by scrupling at unpleasant tasks. This slave has been disobedient and lazy. Slay her for me, and I shall know you have the steel to be my partner."</p>
<p><b>No Skill:</b> <em>You can agree or not:</em></p>
<p><em>If you agree:</em> You do as the other asks, and he is delighted. At last he has found an equal in his ruthless ways! [D-1/S1/W+2 (Max: Princely)/Lose Piety]</p>
<p><em>If you do not:</em> You refuse to do this evil deed, and the other has you beaten as a weakling and a coward before casting you out. Then he spreads lies and calumny about you, that all might despise you, though you know in your heart that you have done as Allah wills. [D2/Piety/<em>Wounded</em>/<em>Scorned</em>]</p>
<p><b>Quick Thinking, Stealth and Stealing:</b> The beauty of intended victim captivates your reason, so you gather the slave up and leap out a window. Your happiness is a tale told long after. [D2/S2/choice of Seduction or <em>Married</em>]</p>`,
	},
	2588: {
		index: 2588,
		text: `<p>A wealthy merchant asks you to track down a wandering order of dervishes. The man is dying and wishes the holy ones to bless him before he passes. He promises suitable payment for their devotions and for your aid.</p>
<p><b>No Skill:</b> The leader of the dervishes refuses your request. The blessings of the order are not for sale. [S1]</p>
<p><b>Beguiling, Bargaining and Evaluation:</b> Knowing that a direct offer of payment would simply insult the holy ones, you attempt a different approach. You indicate that the group can secure a generous offer to a nearby mosque if they can find the grace in their hearts to pray over a dying man. Surely, Allah would approve of such devotion. The dervishes accept. [D1/W+1 (Max: Rich)/<em>Blessed</em> [1 use]]</p>`,
	},
	2589: {
		index: 2589,
		text: `<p>A noble has called for all the surrounding villages to come for the wedding of his daughter! For such a grand occasion, he charges you with securing a holy blessing for the couple. You seek out the most devout in the area, a group of mystical Sufi dervishes. Unsure of what will tempt them to comply, you approach to make your request. The leader of the dervishes refuses to entertain your request until you have been properly purified. You attend every service, dancing and whirling until you are out of breath.</p>
<p><b>No Skill:</b> You tire quickly and gain no enlightenment. Still, the holy ones agree to attend and bless the union, but only on the condition that you undertake the next pilgrimage with them. You agree. [D1/<em>On Pilgrimage</em>]</p>
<p><b>Enduring Hardship:</b> As you fight through your exhaustion, your devotion increases. Soon you find yourself very much attracted to this strange devotion. During the wedding, you refuse your seat at the noble's table and instead sit and dance with your newfound friends. [D1/S1/Piety]</p>`,
	},
	2590: {
		index: 2590,
		text: `<p>After a great adventure, you secure a treasure map. According to the notes on the parchment, the entryway to the valuables is guarded by a magical ward. Only a holy man in the throes of religious fervor may enter. Seeking among a group of dervishes, you find one who will teach you the proper dance to achieve purity. In return, he asks only one thing: That you abandon any material wealth and devote yourself to the ways of Allah.</p>
<p><b>No Skill:</b> Such a bargain gains you nothing. You might gain great treasure but could not enjoy it. [S1]</p>
<p><b>Quick Thinking, Wisdom:</b> You accept. You will have to rid yourself of all your gold, but no doubt the magical treasures to be found in the cave will serve you well as you embark on a new life devoted to Allah. [D2/W−4 (Min: Penniless)/Piety/Draw two <b>Treasures</b>]</p>`,
	},
	2591: {
		index: 2591,
		text: `<p>Something does not sit right, for the other is too beautiful for such a desolate place. You lash out at the other, drawing your scimitar as you shout. The other falls to the ground, the illusion of beauty replaced by the visage of an ugly hag.</p>
<p><b>No Skill:</b> You slay the unholy wretch. [D2/S1/Piety]</p>
<p><b>Magic:</b> Opportunity knocks, and you answer. The ability to change one's visage may prove useful. You trade the wretch's life for the knowledge. [D1/S1/Acting and Disguise]</p>`,
	},
	2592: {
		index: 2592,
		text: `<p>The other smiles at you, and you stand transfixed. You are barely able to mutter out a prayer to Allah, but He hears you and allows you to pull your weapon. The other laughs, and slowly fades into nothingness, a mere illusion.</p>
<p><b>No Skill:</b> At the next town you enter you tell your tale, but the townsfolk laugh at you with incredulity: you cannot even buy water here, let alone get help on your quest. [D1/<em>Insane</em>/<em>Scorned</em>]</p>
<p><b>Storytelling:</b> When you arrive at a nearby town you regale the local inn with your tales of danger and magic. You speak late into the night, and your meals and provisions are more than covered by the tips you receive. [D1/S1/W+1 (Max: Respectable)]</p>`,
	},
	2593: {
		index: 2593,
		text: `<p>You pause for the night at a local inn, exhausted from your long travels and grateful to be out of the wind. The food is good and the room is awash in beautiful young women. However, you notice throughout the evening that men come and go, staying in back rooms and not eating. After seeing some of the women escort a couple of men into hidden rooms, you realize that you have stumbled into a pagan brothel! You try to leave casually, but one of the women—half a head taller than you and as fierce as one of the Amazons of legend—stands before you demanding payment.</p>
<p><b>No Skill:</b> You turn as if to go back in, and then with a burst of speed you shove past the woman and flee as quickly as your limbs will carry you. [D1/Quick Thinking]</p>
<p><b>Quick Thinking, Piety:</b> With surprising speed, you knock down the guard and grab a large sack sitting by her feet. Once safely away, you discover it is full of the ill-gotten gains of the brothel and donate it to a local mosque. [S2/Piety]</p>`,
	},
	2594: {
		index: 2594,
		text: `<p>In the distance you see a lone figure stumbling up the road. You rush to help what turns out to be a beautiful young woman in torn rags. She tells you she was on her way to bring a rare gift to her young husband-to-be as a dowry when she was beset by bandits. If only there was something you could do...</p>
<p><b>No Skill:</b> You offer her a few coins, but she turns them away. What are a few coins to winning the heart of her handsome partner? [S1]</p>
<p><b>Stealth and Stealing:</b> You have an idea. You tell the young woman to go to the nearest inn and wait until nightfall for you to come. She is confused but in no state to argue. You follow the young woman's tracks back to where she was attacked and from there follow the bandits' horse tracks back to their cave. Sneaking inside, you find the gift the woman described and return with it to the inn. The bride is nowhere to be found, and the innkeeper doesn't recognize your description. You decide to hang onto the item until you find her again. [S1/<b>Treasure</b>]</p>
<p><b>Weapon Use:</b> You track down the bandits and challenge their leader. His first swing snaps your scimitar in twain, and the second nearly does the same to your neck! He beats you down and locks you in a cage, hoping for a hefty ransom. [D1/<em>Imprisoned</em>]</p>`,
	},
	2595: {
		index: 2595,
		text: `<p>Traveling along the road your caravan is set upon by a large lizard. It grabs you and you lose consciousness. When you awaken, you find yourself in a dank cave. As your eyes slowly adjust to the darkness, you see a woman sitting there, also badly hurt. Nearby, a nest of tiny legless lizards hiss and cry for food. Suddenly, the giant monster reappears and begins to move towards the other. "This is no way for someone of such beauty to die, so I must give myself first." You throw yourself between you and the unfortunate other, ready for your fate.</p>
<p><b>No Skill:</b> Just as you brace for the gnashing of the beast's terrible jaws, there is the sound of clanking metal as guards from your caravan come to rescue you. The beast, startled by the noise, runs to safety. [S1]</p>
<p><b>Piety:</b> Your peaceful countenance stills the fire in the beast's eyes. Your faith and sacrifice bless you, and the beast steps aside to let you and the beautiful maiden leave. The maiden, a daughter of the local noble, awards you greatly [D1/S1/W+2 (Max: Rich)/Piety]</p>`,
	},
	2596: {
		index: 2596,
		text: `<p>Trying to rest under a large tree, you find yourself uncomfortable in the glaring midday sun. You toss and turn, finally pulling at a large rock on which to place your head. It clanks as you pull it from the rocky soil, and you discover it is not a rock at all, but a rusty copper box! Inside are a letter addressed to a woman and a signet ring made of gold and rubies. The letter inspires your pity, and you set off to deliver it to the intended recipient. At a nearby town, you find an attractive young man on his knees in front of a chaste and pious woman, who is obviously annoyed. You smile and walk up to the pair, handing her the box. "I believe this is yours?"</p>
<p><b>No Skill:</b> The woman is relieved and thanks you profusely. You are offered some of her dowry. You politely refuse, as they will need it for their wedding. [S2/Wisdom]</p>
<p><b>Courtly Graces:</b> The young woman thanks you and tells you that such a kind gesture must be repaid. She invites you to dinner that night, with her father, the Sultan. He treats you with great hospitality, and at the end of the night, gifts you with the gold and ruby ring. He says you may show it to anyone you meet within his lands, and they will show you similar kindness. [D2/S1/W+2 (Max: Princely)/<b>Robe of Honor</b>]</p>`,
	},
	2597: {
		index: 2597,
		text: `<p>Your heart leaps when you first see the wondrous creature. You decide you must have it for your own. But how can you capture such a fine animal alone?</p>
<p><b>No Skill:</b> You can convince no one to aid you in your attempt to enslave the creature. Greed eats at your heart. [D-1/S1/<em>Envious</em>]</p>
<p><b>Bargaining and Evaluation:</b> It costs you dearly, but you are able to hire a band to help you capture the animal. When you do, you discover that having is not nearly so great a joy as wanting. [D1/S1/W−2 (Min: Poor)/Wisdom]</p>`,
	},
	2598: {
		index: 2598,
		text: `<p>You are amazed by the fine steed you see outside the stables of the emir. You wonder how you might acquire such a mount for yourself and seek help from a local merchant friend.</p>
<p><b>No Skill:</b> The merchant tells you that you could not hope to purchase the horse, for it belongs to a distant cousin of the emir who is due any day to reclaim it. Together, you make a plan to disguise yourself as the emir's cousin and trick the emir into giving you the horse. [S1/W+1 (Max: Rich)/Acting and Disguise]</p>
<p><b>Piety</b> (mandatory): When your friend tells you the story of the owner of the horse, you realize that you cannot with clear conscience steal such a wondrous beast. You leave empty-handed but with a warm heart. [D1]</p>`,
	},
	2599: {
		index: 2599,
		text: `<p>You chance upon a fine steed, mired in a pit of mud. Despite your best efforts, you cannot free the animal without aid. You pray to the Most Merciful that you can return in time.</p>
<p><b>No Skill:</b> Fortunately, you encounter a ferryman nearby. With his knowledge of ropes and tack, you are able to free the animal together. [D1/Seamanship]</p>
<p><b>Magic:</b> After searching in vain for an hour for anyone to aid you, it is clear that you will not have enough time. Rather than let the creature die, you risk summoning a tiny djinn to help you. He is impressed by your generosity, and declares that henceforth your nobility of spirit shall be clear for all to see. [D1/S1/Appearance]</p>`,
	},
	2600: {
		index: 2600,
		text: `<p>Praise unto Allah, Who alone is without error, for allowing His worthless servants to complete this manuscript!</p>
<p><b>No Skill:</b> You throw yourself down a well. It's a long way down. [D-1/S1/<em>Wounded</em>]</p>
<p><b>Determined</b> (mandatory), <b>Enduring Hardship:</b> You decide that the original well wasn't big enough, so you dig and dig until it has doubled its original size. Only then do you hurl yourself down into it. [D1/S1/<em>Fated</em>]</p>
<p><b>Piety:</b> It is said that the carpet-weavers of Persia deliberately introduce a flaw into every carpet, for only the Most High can make a thing that is perfect. Truly, in this regard if in no other, Allah is most pleased with this Book of Tales—but He throws you down a well for good measure. [D1/S1/<em>Humility</em>]</p>
<p><b>Enslaved</b> (mandatory): You are thrown down a well. The water in the well is brown, not blue. [D-1/S-1/<em>Grief Stricken</em>]</p>
<p><b>Sultan</b> (mandatory): Eric has Anthony, Kevin, and Zev hurled down a well. It is clear than cannibalism cannot be far behind. [D2/S2/<em>Insane</em>]</p>
<p><b>Storytelling:</b> You understand that repetition is the key to humor. However, The Reader has heard this one before, and throws you down a well. [D1/S-1/<em>Scorned</em>]</p>`,
	},
};
